///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // showObj(txb_isurcd, false);    // 히든처리!
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(penel_1);
        await scwin.setCode();

        // 가우스헤더 셋팅
        const sbmOptions = {
            id : "sbm_dts_file_save",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_file_save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 파일: 가우스헤더 셋팅

        // dts_fileData.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_fileData.insertRow();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35119.onpageload" });
    }
};

/**
 * @method
