///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    txb_reg_emp_nm.setValue(js_emp_nm);
    // 벌점부과유형  셋팅
    const sbmOptions = {
        id : "sbm_dts_CautnActRsn",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_CautnActRsn=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name save
 * @description 등록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // 등록
    // 초기화
    dts_file_save.removeAll();
    if (scwin.gIsurCd === "") {
        await $c.win.alert("벌점입력화면에서 법인을 조회 후 등록가능합니다.");
        return;
    }

    /*
    		if(getObjectValue(txb_file_nm) == "" ) {
    			alert("첨부파일을  입력해주세요");
    			inf_find.focus();
    			return;
    		}
     */

    if (txb_file_nm.getValue().length > 80) {
        await $c.win.alert("첨부파일명 길이 80자리를 초과했습니다.");
        txb_file_nm.focus();
        return;
    }
    dts_file_save.insertRow();
    dts_file_save.setCellData(1, "ISUR_CD", scwin.gIsurCd);
    dts_file_save.setCellData(1, "RPT_DD", edt_rpt_dd.getValue());
    dts_file_save.setCellData(1, "CAUTN_ACT_RSN_CD", cmb_cautn_act_rsn.getValue());
    dts_file_save.setCellData(1, "EMP_NO", js_emp_no);
    dts_file_save.setCellData(1, "END_DD", edt_end_dd.getValue());
    dts_file_save.setCellData(1, "ATTACH_FILE_NM", txb_file_nm.getValue());
    dts_file_save.setCellData(1, "REMK", txa_remk.getValue());
    let vAnswer;
    vAnswer = confirm('주의조치 정보를 저장 하시겠습니까?');
    if (vAnswer === true) {
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/PenaltyImposition.do",
            ref : "dts_file_save,dts_fileData",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

