///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkGraceInfo
 * @description PopupCalendar에서 호출함. 공통으로 사용해서~ 껍질만 들고옴. 이 화면에서는 만료일 구해오는게 하나라 gubunPNLT 의미 없음
 * @param {*} gubunPNLT gubunPNLT
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkGraceInfo = async function(gubunPNLT) {
    await scwin.getIn6months();
};

/**
 * @method
 * @name getIn60days_old
 * @description 달력일로 변경old 스크립트로 호출하면 2022-08-09 +6개월 하면 2023-03-01 이 나오는데 2022-2-02-28로 나와야 한다고해서 오라클 콜로 바꿈.
 * @returns {void}
 * @hidden N
 */
scwin.getIn60days_old = function() {
    const rpt_dd = edt_rpt_dd.getValue();
    const inp_year = rpt_dd.substr(0, 4);
    const inp_month = rpt_dd.substr(4, 2) - 1;
    const inp_day = rpt_dd.substr(6, 2);
    const date = new Date(inp_year, inp_month, inp_day);
    date.setMonth(date.getMonth() + 6);
    let month = (date.getMonth() + 1);
    if ((month + "").length === 1) month = "0" + month;
    let day = date.getDate();
    if ((day + "").length === 1) day = "0" + day;
    edt_end_dd.setValue(date.getFullYear() + "" + month + "" + day);
};
